namespace ClashSharp.Installer.Presentation;

internal static partial class InstallerTranslations
{
    // Source, Traditional Chinese, English, Russian, French, German, Persian, Korean.
    private static readonly string[][] Part2 =
    [
        ["安装包签名尚未受信任", "安裝套件的簽章尚未受信任", "The package signature is not trusted yet", "Подпись пакета пока не является доверенной", "La signature du paquet n'est pas encore approuvée", "Die Paketsignatur ist noch nicht vertrauenswürdig", "امضای بسته هنوز مورد اعتماد نیست", "패키지 서명을 아직 신뢰할 수 없음"],
        ["Windows 未能确认此安装包的来源。请从项目的 GitHub Release 重新下载完整压缩包，完整解压后运行 Setup.exe。若仍失败，请向提供者反馈诊断代码。", "Windows 無法確認此安裝套件的來源。請從專案的 GitHub Release 重新下載完整的壓縮檔，完整解壓縮後執行 Setup.exe。若仍失敗，請向提供者回報診斷代碼。", "Windows could not confirm where this package comes from. Download the complete archive again from the project's GitHub Releases, extract all of it, then run Setup.exe. If it still fails, report the diagnostic code to the provider.", "Windows не удалось подтвердить происхождение пакета. Снова скачайте полный архив со страницы GitHub Releases проекта, полностью распакуйте его и запустите Setup.exe. Если ошибка повторится, сообщите код диагностики поставщику.", "Windows n'a pas pu confirmer l'origine de ce paquet. Téléchargez de nouveau l'archive complète depuis les GitHub Releases du projet, extrayez-la entièrement, puis lancez Setup.exe. Si l'échec persiste, transmettez le code de diagnostic au fournisseur.", "Windows konnte die Herkunft dieses Pakets nicht bestätigen. Laden Sie das vollständige Archiv erneut von den GitHub Releases des Projekts herunter, entpacken Sie es vollständig und starten Sie Setup.exe. Schlägt es weiterhin fehl, melden Sie den Diagnosecode dem Anbieter.", "Windows نتوانست منبع این بسته را تأیید کند. بایگانی کامل را دوباره از GitHub Releases پروژه بارگیری کنید، آن را کامل از حالت فشرده خارج کنید و سپس Setup.exe را اجرا کنید. اگر باز هم ناموفق بود، کد عیب‌یابی را به ارائه‌دهنده گزارش دهید.", "Windows에서 이 패키지의 출처를 확인하지 못했습니다. 프로젝트의 GitHub Releases에서 전체 압축 파일을 다시 내려받아 모두 압축을 푼 다음 Setup.exe를 실행하세요. 그래도 실패하면 제공자에게 진단 코드를 알려 주세요."],
        ["安装包签名证书已过期", "安裝套件的簽章憑證已過期", "The package's signing certificate has expired", "Срок действия сертификата подписи пакета истёк", "Le certificat de signature du paquet a expiré", "Das Signaturzertifikat des Pakets ist abgelaufen", "گواهی امضای بسته منقضی شده است", "패키지 서명 인증서가 만료됨"],
        ["请检查电脑的日期和时间，并向安装包提供者获取新版本。完整解压新安装包后，再运行 Setup.exe。", "請檢查電腦的日期和時間，並向安裝套件提供者取得新版本。完整解壓縮新的安裝套件後，再執行 Setup.exe。", "Check the computer's date and time, and get a new version from the package provider. Extract the new package completely, then run Setup.exe.", "Проверьте дату и время на компьютере и получите новую версию у поставщика пакета. Полностью распакуйте новый пакет, затем запустите Setup.exe.", "Vérifiez la date et l'heure de l'ordinateur, et procurez-vous une nouvelle version auprès du fournisseur du paquet. Extrayez entièrement le nouveau paquet, puis lancez Setup.exe.", "Prüfen Sie Datum und Uhrzeit des Computers und besorgen Sie eine neue Version beim Anbieter des Pakets. Entpacken Sie das neue Paket vollständig und starten Sie dann Setup.exe.", "تاریخ و ساعت رایانه را بررسی کنید و نسخهٔ جدید را از ارائه‌دهندهٔ بسته بگیرید. بستهٔ جدید را کامل از حالت فشرده خارج کنید و سپس Setup.exe را اجرا کنید.", "컴퓨터의 날짜와 시간을 확인하고, 패키지 제공자에게서 새 버전을 받으세요. 새 패키지의 압축을 모두 푼 다음 Setup.exe를 실행하세요."],
        ["安装包签名证书已被撤销", "安裝套件的簽章憑證已遭撤銷", "The package's signing certificate has been revoked", "Сертификат подписи пакета отозван", "Le certificat de signature du paquet a été révoqué", "Das Signaturzertifikat des Pakets wurde widerrufen", "گواهی امضای بسته باطل شده است", "패키지 서명 인증서가 해지됨"],
        ["请向安装包提供者获取使用有效证书签名的新版本，完整解压后运行 Setup.exe。", "請向安裝套件提供者取得以有效憑證簽署的新版本，完整解壓縮後執行 Setup.exe。", "Get a new version signed with a valid certificate from the package provider, extract it completely, then run Setup.exe.", "Получите у поставщика новую версию, подписанную действительным сертификатом, полностью распакуйте её и запустите Setup.exe.", "Procurez-vous auprès du fournisseur une nouvelle version signée avec un certificat valide, extrayez-la entièrement, puis lancez Setup.exe.", "Besorgen Sie beim Anbieter eine neue, mit gültigem Zertifikat signierte Version, entpacken Sie sie vollständig und starten Sie Setup.exe.", "نسخهٔ جدیدی را که با گواهی معتبر امضا شده است از ارائه‌دهنده بگیرید، آن را کامل از حالت فشرده خارج کنید و Setup.exe را اجرا کنید.", "패키지 제공자에게서 유효한 인증서로 서명된 새 버전을 받아 압축을 모두 푼 다음 Setup.exe를 실행하세요."],
        ["安装包缺少有效签名", "安裝套件缺少有效的簽章", "The package has no valid signature", "У пакета нет действительной подписи", "Le paquet n'a pas de signature valide", "Das Paket hat keine gültige Signatur", "بسته امضای معتبر ندارد", "패키지에 유효한 서명이 없음"],
        ["请重新获取完整安装包，完整解压后运行其中的 Setup.exe，并保留随附文件。", "請重新取得完整的安裝套件，完整解壓縮後執行其中的 Setup.exe，並保留隨附檔案。", "Get the complete package again, extract it completely, run the Setup.exe inside, and keep the files that come with it.", "Снова получите полный пакет, полностью распакуйте его, запустите находящийся в нём Setup.exe и сохраните сопутствующие файлы.", "Récupérez de nouveau le paquet complet, extrayez-le entièrement, lancez le Setup.exe qu'il contient et conservez les fichiers fournis.", "Beschaffen Sie das vollständige Paket erneut, entpacken Sie es vollständig, starten Sie die enthaltene Setup.exe und behalten Sie die mitgelieferten Dateien.", "بستهٔ کامل را دوباره بگیرید، آن را کامل از حالت فشرده خارج کنید، Setup.exe داخل آن را اجرا کنید و فایل‌های همراه را نگه دارید.", "전체 패키지를 다시 받아 압축을 모두 풀고 그 안의 Setup.exe를 실행하세요. 함께 제공된 파일은 그대로 두세요."],
        ["安装包签名校验失败", "安裝套件簽章驗證失敗", "Package signature verification failed", "Не удалось проверить подпись пакета", "Échec de la vérification de la signature du paquet", "Prüfung der Paketsignatur fehlgeschlagen", "بررسی امضای بسته ناموفق بود", "패키지 서명 확인 실패"],
        ["安装器文件可能已损坏、被修改，或与安装载荷不属于同一版本。请重新获取完整安装包，完整解压后运行其中的 Setup.exe。", "安裝程式檔案可能已損毀、遭修改，或與安裝內容不屬於同一版本。請重新取得完整的安裝套件，完整解壓縮後執行其中的 Setup.exe。", "The installer file may be damaged, modified, or from a different version than its payload. Get the complete package again, extract it completely, and run the Setup.exe inside.", "Файл установщика может быть повреждён, изменён или относиться к другой версии, чем его содержимое. Снова получите полный пакет, полностью распакуйте его и запустите находящийся в нём Setup.exe.", "Le fichier du programme d'installation est peut-être endommagé, modifié ou d'une autre version que son contenu. Récupérez de nouveau le paquet complet, extrayez-le entièrement et lancez le Setup.exe qu'il contient.", "Die Datei des Installationsprogramms ist möglicherweise beschädigt, verändert oder gehört zu einer anderen Version als ihr Inhalt. Beschaffen Sie das vollständige Paket erneut, entpacken Sie es vollständig und starten Sie die enthaltene Setup.exe.", "ممکن است فایل نصب‌کننده آسیب دیده، تغییر کرده یا با محتوای نصب از یک نسخه نباشد. بستهٔ کامل را دوباره بگیرید، آن را کامل از حالت فشرده خارج کنید و Setup.exe داخل آن را اجرا کنید.", "설치 프로그램 파일이 손상되었거나 수정되었거나, 설치 내용과 다른 버전일 수 있습니다. 전체 패키지를 다시 받아 압축을 모두 풀고 그 안의 Setup.exe를 실행하세요."],
        ["无法确认原安装可恢复", "無法確認原有安裝可以還原", "Cannot confirm the original installation can be restored", "Не удаётся подтвердить, что исходную установку можно восстановить", "Impossible de confirmer que l'installation d'origine peut être restaurée", "Wiederherstellbarkeit der ursprünglichen Installation nicht bestätigt", "امکان بازگردانی نصب اصلی تأیید نشد", "원래 설치를 복원할 수 있는지 확인할 수 없음"],
        ["原包、文件或服务状态已改变，或恢复记录不完整。请使用此安装器重新检查并继续完成安装。", "原有的套件、檔案或服務狀態已改變，或復原記錄不完整。請使用此安裝程式重新檢查並繼續完成安裝。", "The original package, files or service changed, or the recovery record is incomplete. Check again with this installer and finish the installation.", "Исходный пакет, файлы или служба изменились, либо запись восстановления неполна. Проверьте ещё раз этим установщиком и завершите установку.", "Le paquet, les fichiers ou le service d'origine ont changé, ou l'enregistrement de récupération est incomplet. Revérifiez avec ce programme d'installation et terminez l'installation.", "Ursprüngliches Paket, Dateien oder Dienst haben sich geändert, oder der Wiederherstellungsdatensatz ist unvollständig. Prüfen Sie mit diesem Installationsprogramm erneut und schließen Sie die Installation ab.", "بستهٔ اصلی، فایل‌ها یا وضعیت سرویس تغییر کرده یا سابقهٔ بازیابی ناقص است. با همین نصب‌کننده دوباره بررسی کنید و نصب را کامل کنید.", "원래 패키지, 파일 또는 서비스 상태가 바뀌었거나 복구 기록이 불완전합니다. 이 설치 프로그램으로 다시 확인하고 설치를 마치세요."],
        ["安装文件校验失败", "安裝檔案驗證失敗", "Installation file verification failed", "Не удалось проверить установочные файлы", "Échec de la vérification des fichiers d'installation", "Prüfung der Installationsdateien fehlgeschlagen", "بررسی فایل‌های نصب ناموفق بود", "설치 파일 확인 실패"],
        ["文件可能已损坏或与此安装器不匹配。请重新获取同一版本的完整安装包，完整解压后运行其中的安装器，并保留全部随附文件。", "檔案可能已損毀或與此安裝程式不相符。請重新取得同一版本的完整安裝套件，完整解壓縮後執行其中的安裝程式，並保留全部隨附檔案。", "The files may be damaged or may not match this installer. Get the complete package of the same version again, extract it completely, run the installer inside, and keep all the files that come with it.", "Файлы могут быть повреждены или не соответствовать этому установщику. Снова получите полный пакет той же версии, полностью распакуйте его, запустите находящийся в нём установщик и сохраните все сопутствующие файлы.", "Les fichiers sont peut-être endommagés ou ne correspondent pas à ce programme d'installation. Récupérez de nouveau le paquet complet de la même version, extrayez-le entièrement, lancez le programme d'installation qu'il contient et conservez tous les fichiers fournis.", "Die Dateien sind möglicherweise beschädigt oder passen nicht zu diesem Installationsprogramm. Beschaffen Sie das vollständige Paket derselben Version erneut, entpacken Sie es vollständig, starten Sie das enthaltene Installationsprogramm und behalten Sie alle mitgelieferten Dateien.", "ممکن است فایل‌ها آسیب دیده باشند یا با این نصب‌کننده مطابقت نداشته باشند. بستهٔ کامل همان نسخه را دوباره بگیرید، آن را کامل از حالت فشرده خارج کنید، نصب‌کنندهٔ داخل آن را اجرا کنید و همهٔ فایل‌های همراه را نگه دارید.", "파일이 손상되었거나 이 설치 프로그램과 맞지 않을 수 있습니다. 같은 버전의 전체 패키지를 다시 받아 압축을 모두 풀고 그 안의 설치 프로그램을 실행하세요. 함께 제공된 파일은 모두 그대로 두세요."],
        ["安装文件不完整或不匹配", "安裝檔案不完整或不相符", "Installation files incomplete or mismatched", "Установочные файлы неполны или не соответствуют", "Fichiers d'installation incomplets ou incohérents", "Installationsdateien unvollständig oder unpassend", "فایل‌های نصب ناقص یا نامتناسب‌اند", "설치 파일이 불완전하거나 맞지 않음"],
        ["请重新获取同一版本的完整安装包，完整解压后运行其中的安装器，并保留全部随附文件，不要混用其他版本的文件。", "請重新取得同一版本的完整安裝套件，完整解壓縮後執行其中的安裝程式，並保留全部隨附檔案，不要混用其他版本的檔案。", "Get the complete package of the same version again, extract it completely, run the installer inside, and keep all the files that come with it. Do not mix in files from other versions.", "Снова получите полный пакет той же версии, полностью распакуйте его, запустите находящийся в нём установщик и сохраните все сопутствующие файлы. Не смешивайте файлы разных версий.", "Récupérez de nouveau le paquet complet de la même version, extrayez-le entièrement, lancez le programme d'installation qu'il contient et conservez tous les fichiers fournis. Ne mélangez pas de fichiers d'autres versions.", "Beschaffen Sie das vollständige Paket derselben Version erneut, entpacken Sie es vollständig, starten Sie das enthaltene Installationsprogramm und behalten Sie alle mitgelieferten Dateien. Mischen Sie keine Dateien anderer Versionen.", "بستهٔ کامل همان نسخه را دوباره بگیرید، آن را کامل از حالت فشرده خارج کنید، نصب‌کنندهٔ داخل آن را اجرا کنید و همهٔ فایل‌های همراه را نگه دارید. فایل‌های نسخه‌های دیگر را با آن‌ها ترکیب نکنید.", "같은 버전의 전체 패키지를 다시 받아 압축을 모두 풀고 그 안의 설치 프로그램을 실행하세요. 함께 제공된 파일은 모두 그대로 두고, 다른 버전의 파일을 섞지 마세요."],
        ["无法读取安装文件", "無法讀取安裝檔案", "Cannot read the installation files", "Не удаётся прочитать установочные файлы", "Impossible de lire les fichiers d'installation", "Installationsdateien nicht lesbar", "خواندن فایل‌های نصب ممکن نیست", "설치 파일을 읽을 수 없음"],
        ["请关闭正在使用这份安装包的其他程序，将完整压缩包解压到新的本机文件夹，再从该目录运行 Setup.exe。", "請關閉正在使用這份安裝套件的其他程式，將完整的壓縮檔解壓縮到新的本機資料夾，再從該資料夾執行 Setup.exe。", "Close other programs that are using this package, extract the complete archive to a new local folder, and run Setup.exe from there.", "Закройте другие программы, использующие этот пакет, распакуйте полный архив в новую локальную папку и запустите Setup.exe оттуда.", "Fermez les autres programmes qui utilisent ce paquet, extrayez l'archive complète dans un nouveau dossier local, puis lancez Setup.exe depuis ce dossier.", "Schließen Sie andere Programme, die dieses Paket verwenden, entpacken Sie das vollständige Archiv in einen neuen lokalen Ordner und starten Sie Setup.exe von dort.", "برنامه‌های دیگری را که از این بسته استفاده می‌کنند ببندید، بایگانی کامل را در یک پوشهٔ محلی جدید از حالت فشرده خارج کنید و Setup.exe را از همان‌جا اجرا کنید.", "이 패키지를 사용 중인 다른 프로그램을 닫고, 전체 압축 파일을 새 로컬 폴더에 푼 다음 그 폴더에서 Setup.exe를 실행하세요."],
        ["已有安装操作正在执行", "已有安裝操作正在執行", "Another installation operation is running", "Уже выполняется другая операция установки", "Une autre opération d'installation est en cours", "Ein anderer Installationsvorgang läuft bereits", "عملیات نصب دیگری در حال اجراست", "다른 설치 작업이 실행 중임"],
        ["请等待另一项安装、修复或卸载操作完成，再使用原安装器重新检查。", "請等待另一項安裝、修復或解除安裝操作完成，再使用原本的安裝程式重新檢查。", "Wait for the other installation, repair or uninstallation to finish, then check again with the original installer.", "Дождитесь завершения другой установки, исправления или удаления, затем проверьте ещё раз исходным установщиком.", "Attendez la fin de l'autre installation, réparation ou désinstallation, puis revérifiez avec le programme d'installation d'origine.", "Warten Sie, bis die andere Installation, Reparatur oder Deinstallation abgeschlossen ist, und prüfen Sie dann mit dem ursprünglichen Installationsprogramm erneut.", "منتظر بمانید تا نصب، تعمیر یا حذف دیگر تمام شود، سپس با نصب‌کنندهٔ اصلی دوباره بررسی کنید.", "다른 설치, 복구 또는 제거 작업이 끝날 때까지 기다린 다음 원래 설치 프로그램으로 다시 확인하세요."],
        ["无法建立安装会话", "無法建立安裝工作階段", "Cannot start an installation session", "Не удаётся начать сеанс установки", "Impossible d'ouvrir une session d'installation", "Installationssitzung kann nicht gestartet werden", "ایجاد نشست نصب ممکن نیست", "설치 세션을 시작할 수 없음"],
        ["请确认没有其他安装器正在执行操作；如有，请等待其完成，再使用原安装器重新检查。如果仍然失败，请保留诊断代码以便排查。", "請確認沒有其他安裝程式正在執行操作；如有，請等待其完成，再使用原本的安裝程式重新檢查。如果仍然失敗，請保留診斷代碼以便排查。", "Make sure no other installer is running an operation; if one is, wait for it to finish, then check again with the original installer. If it still fails, keep the diagnostic code for troubleshooting.", "Убедитесь, что никакой другой установщик не выполняет операцию; если выполняет, дождитесь её завершения и проверьте ещё раз исходным установщиком. Если ошибка повторится, сохраните код диагностики для поиска причины.", "Vérifiez qu'aucun autre programme d'installation n'exécute d'opération ; le cas échéant, attendez qu'elle se termine, puis revérifiez avec le programme d'installation d'origine. Si l'échec persiste, conservez le code de diagnostic pour le dépannage.", "Stellen Sie sicher, dass kein anderes Installationsprogramm einen Vorgang ausführt; falls doch, warten Sie, bis er abgeschlossen ist, und prüfen Sie dann mit dem ursprünglichen Installationsprogramm erneut. Schlägt es weiterhin fehl, bewahren Sie den Diagnosecode zur Fehlersuche auf.", "مطمئن شوید هیچ نصب‌کنندهٔ دیگری در حال انجام عملیات نیست؛ اگر هست، منتظر بمانید تا تمام شود و سپس با نصب‌کنندهٔ اصلی دوباره بررسی کنید. اگر باز هم ناموفق بود، کد عیب‌یابی را برای رفع مشکل نگه دارید.", "다른 설치 프로그램이 작업을 실행하고 있지 않은지 확인하세요. 실행 중이면 끝날 때까지 기다린 다음 원래 설치 프로그램으로 다시 확인하세요. 그래도 실패하면 문제 해결을 위해 진단 코드를 보관하세요."],
        ["已安装更新的版本", "已安裝較新的版本", "A newer version is installed", "Установлена более новая версия", "Une version plus récente est installée", "Eine neuere Version ist installiert", "نسخهٔ جدیدتری نصب است", "더 새로운 버전이 설치됨"],
        ["此电脑上的 Clash# 比此安装包更新，安装器不会降级，系统未被更改。如需修复，请使用相同或更新版本的安装包；也可以重新检查后在此卸载。", "此電腦上的 Clash# 比此安裝套件新，安裝程式不會降級，系統未遭變更。如需修復，請使用相同或更新版本的安裝套件；也可以重新檢查後在此解除安裝。", "Clash# on this computer is newer than this package. The installer does not downgrade, and the system was not changed. To repair, use a package of the same or a newer version; you can also check again and uninstall here.", "Clash# на этом компьютере новее, чем этот пакет. Установщик не выполняет понижение версии, система не изменена. Для исправления используйте пакет той же или более новой версии; также можно проверить ещё раз и удалить приложение здесь.", "Clash# sur cet ordinateur est plus récent que ce paquet. Le programme d'installation ne rétrograde pas et le système n'a pas été modifié. Pour réparer, utilisez un paquet de la même version ou plus récent ; vous pouvez aussi revérifier et désinstaller ici.", "Clash# auf diesem Computer ist neuer als dieses Paket. Das Installationsprogramm führt kein Downgrade durch, das System wurde nicht verändert. Verwenden Sie zum Reparieren ein Paket derselben oder einer neueren Version; Sie können auch erneut prüfen und hier deinstallieren.", "Clash# روی این رایانه از این بسته جدیدتر است. نصب‌کننده نسخه را پایین نمی‌آورد و سیستم تغییری نکرده است. برای تعمیر از بستهٔ همان نسخه یا جدیدتر استفاده کنید؛ همچنین می‌توانید دوباره بررسی کنید و اینجا حذف کنید.", "이 컴퓨터의 Clash#가 이 패키지보다 새롭습니다. 설치 프로그램은 다운그레이드하지 않으며 시스템은 변경되지 않았습니다. 복구하려면 같거나 더 새로운 버전의 패키지를 사용하세요. 다시 확인한 뒤 여기서 제거할 수도 있습니다."],
        ["卸载完成。", "解除安裝完成。", "Uninstallation completed.", "Удаление завершено.", "Désinstallation terminée.", "Deinstallation abgeschlossen.", "حذف کامل شد.", "제거를 완료했습니다."],
        ["卸载已完成", "解除安裝已完成", "Uninstallation completed", "Удаление завершено", "Désinstallation terminée", "Deinstallation abgeschlossen", "حذف تکمیل شد", "제거 완료"],
        ["Clash# 已从此电脑移除。可以关闭安装器，或重新检查以再次安装。", "Clash# 已從此電腦移除。可以關閉安裝程式，或重新檢查以再次安裝。", "Clash# was removed from this computer. You can close the installer, or check again to install it again.", "Clash# удалён с этого компьютера. Можно закрыть установщик или проверить ещё раз, чтобы установить приложение снова.", "Clash# a été supprimé de cet ordinateur. Vous pouvez fermer le programme d'installation, ou revérifier pour le réinstaller.", "Clash# wurde von diesem Computer entfernt. Sie können das Installationsprogramm schließen oder erneut prüfen, um es wieder zu installieren.", "Clash# از این رایانه حذف شد. می‌توانید نصب‌کننده را ببندید یا برای نصب دوباره، دوباره بررسی کنید.", "Clash#를 이 컴퓨터에서 제거했습니다. 설치 프로그램을 닫거나, 다시 확인하여 다시 설치할 수 있습니다."],
        ["卸载已完成，部分目录已保留", "解除安裝已完成，部分資料夾已保留", "Uninstalled; some folders were kept", "Удаление завершено, некоторые папки сохранены", "Désinstallation terminée, certains dossiers conservés", "Deinstalliert; einige Ordner wurden behalten", "حذف تکمیل شد؛ برخی پوشه‌ها حفظ شدند", "제거 완료, 일부 폴더는 유지됨"],
        ["以下目录含有其他内容，或无法确认由安装器创建，因此已保留：", "下列資料夾含有其他內容，或無法確認由安裝程式建立，因此已保留：", "These folders contain other content, or could not be confirmed as created by the installer, so they were kept:", "Следующие папки содержат другое содержимое или не удалось подтвердить, что их создал установщик, поэтому они сохранены:", "Ces dossiers contiennent d'autres éléments, ou leur création par le programme d'installation n'a pas pu être confirmée ; ils ont donc été conservés :", "Diese Ordner enthalten weitere Inhalte oder konnten nicht als vom Installationsprogramm erstellt bestätigt werden und wurden daher behalten:", "این پوشه‌ها محتوای دیگری دارند یا ایجادشان توسط نصب‌کننده تأیید نشد، بنابراین حفظ شدند:", "다음 폴더에는 다른 내용이 있거나 설치 프로그램이 만들었는지 확인할 수 없어 유지했습니다."],
        ["{0}：包含其他内容。", "{0}：包含其他內容。", "{0}: contains other content.", "{0}: содержит другое содержимое.", "{0} : contient d'autres éléments.", "{0}: enthält weitere Inhalte.", "{0}: محتوای دیگری دارد.", "{0}: 다른 내용이 있습니다."],
